import{z as i,x as A,o as n,c as d,q as o,j as l,D as E,d as s,s as r,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"商业周期事实","description":"","frontmatter":{"title":"商业周期事实","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/business-cycle-facts.md","filePath":"econ/business-cycle-facts.md","lastUpdated":1791063341000}'),p={name:"econ/business-cycle-facts.md"};function c(m,a,u,C,f,h){const t=A("Mermaid");return n(),d("div",null,[a[2]||(a[2]=o('<h1 id="商业周期事实" tabindex="-1">商业周期事实 <a class="header-anchor" href="#商业周期事实" aria-label="Permalink to &quot;商业周期事实&quot;">​</a></h1><div class="epigraph"><p>消费比产出平滑，投资更剧烈，工时与产出共动，实际工资弱共动——这些是模型要复制的共动，不是冲击的名字。</p><footer>—— Burns and Mitchell 的周期年表；Kydland and Prescott 的矩表；Stock and Watson, Business Cycle Fluctuations in U.S. Macroeconomic Time Series, Handbook of Macroeconomics</footer></div><p><a href="/econ/hp-filter-cycles">上一课</a>声明周期是滤波后的对象。本课缺口是<strong>事实清单</strong>：共动与相对波动，作为校准靶与模型分类器。不重讲 λ，不把事实写成 SVAR 冲击。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>战后美国（及其它发达经济）HP 后的典型图景：\\(\\sigma(c)\\lt \\sigma(y)\\lt \\sigma(i)\\)；工时强顺周期；劳动生产率顺周期但弱于产出；通胀与产出的共动随样本变；名义利率顺周期较弱。Kydland–Prescott 用技术冲击的 RBC 去对其中若干条，劳动波动与生产率往往是短板。NK 加入需求与粘性后，另一些矩改善，另一些（通胀持续性）靠指数化或习惯。缺口是把「要匹配的是共动」钉住，而不是从零讲什么是衰退。</p><p><span class="marginnote">Stock and Watson, <em>Handbook of Macroeconomics</em> 第 1 卷。Chari, Kehoe and McGrattan 的「Wedges」把事实改写成效率、劳动、投资、需求四个楔，是诊断而不是命名冲击。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>报告：相对标准差、同期相关、自相关、与产出的领先滞后。国际：产出共动、净出口逆周期，是开放经济后课的靶，本课只点名。大稳定（Great Moderation）改变σ的水平，相对矩较稳——样本要声明。新兴市场：消费往往比产出更波动，校准不能照搬美国表。</p><p><span class="marginnote">数字实例：战后美国数据里，投资的标准差约为产出的 3 倍，非耐用品与服务的消费约为产出的七成上下。模型的模拟矩若把这两个大小关系算反了，与靶表的对照一眼就能看出问题。</span></p>',9)),(n(),l(B,null,{default:E(()=>[r(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HP%5B%22%E6%BB%A4%E6%B3%A2%E5%90%8E%E5%BA%8F%E5%88%97%22%5D%20--%3E%20REL%5B%22%E7%9B%B8%E5%AF%B9%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20HP%20--%3E%20COR%5B%22%E5%85%B1%E5%8A%A8%E4%B8%8E%E9%A2%86%E5%85%88%E6%BB%9E%E5%90%8E%22%5D%0A%20%20REL%20--%3E%20TGT%5B%22%E6%A0%A1%E5%87%86%E9%9D%B6%22%5D%0A%20%20COR%20--%3E%20TGT%0A%20%20TGT%20--%3E%20MOD%5B%22RBC%20%2F%20NK%20%2F%20%E5%90%8E%E8%AF%BE%E5%BC%82%E8%B4%A8%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"事实不识别冲击：同一套共动可被技术、需求、金融多种结构生成。下一课 SVAR 才问「若施加识别，脉冲长什么样」。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是加总账户加行为。消费平滑来自欧拉（完全市场下更强）；投资剧烈来自 \\(q\\) 与调整、或来自冲击本身；工时共动要求劳动供给弹性或需求侧拉动。工资弱共动曾被当成黏性证据，也可来自组合的劳动质量或自选择。把单一矩当成单一理论的判决，会输给下一张表。",-1)),a[6]||(a[6]=e("p",null,"代表性模型匹配加总矩，可以与微观 MPC、财富分布同时失败——那是下一单元的入口，本课先把加总事实当公共靶。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"Burns and Mitchell, NBER。现代矩表是它们的二阶矩后代，失去了「转折点年表」的非线性味道；Hamilton 与 Harding–Pagan 的转折点是另一刀。")],-1)),a[8]||(a[8]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：消费平滑像用蓄水池喝水——收入忽多忽少，杯子里的水（消费）却按固定节奏取；多出来的先存进池子，缺的先抽存粮。于是进出水口（投资）的流量最湍急，杯子（消费）最平静，管道（工时）随压力伸缩。")],-1)),(n(),l(B,null,{default:E(()=>[r(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E4%BA%A7%E5%87%BA%20y%20%E8%A2%AB%E5%86%B2%E5%87%BB%E6%89%93%E5%87%BA%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20C%5B%22%E5%AE%B6%E5%BA%AD%E6%8C%89%E6%AC%A7%E6%8B%89%E6%96%B9%E7%A8%8B%E8%B7%A8%E6%9C%9F%E5%B9%B3%E6%BB%91%E6%B6%88%E8%B4%B9%22%5D%0A%20%20C%20--%3E%20F1%5B%22%CF%83(c)%20%E4%BD%8E%E4%BA%8E%20%CF%83(y)%22%5D%0A%20%20Y%20--%3E%20I%5B%22%E5%A4%9A%E4%BD%99%E7%9A%84%E6%B3%A2%E5%8A%A8%E7%81%8C%E8%BF%9B%E6%8A%95%E8%B5%84%E4%B8%8E%E5%BA%93%E5%AD%98%22%5D%0A%20%20I%20--%3E%20F2%5B%22%CF%83(i)%20%E9%AB%98%E4%BA%8E%20%CF%83(y)%2C%20%E4%B8%94%E6%9C%80%E5%89%A7%E7%83%88%22%5D%0A%20%20Y%20--%3E%20H%5B%22%E5%8E%82%E5%95%86%E6%B2%BF%E5%8A%B3%E5%8A%A8%E9%9C%80%E6%B1%82%E8%B0%83%E6%95%B4%E5%B7%A5%E6%97%B6%E4%B8%8E%E9%9B%87%E7%94%A8%22%5D%0A%20%20H%20--%3E%20F3%5B%22%E5%B7%A5%E6%97%B6%E5%BC%BA%E9%A1%BA%E5%91%A8%E6%9C%9F%2C%20%E5%B7%A5%E8%B5%84%E5%8F%AA%E5%BC%B1%E5%85%B1%E5%8A%A8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=o('<p>这张图回答的是：矩表上「消费最平滑、投资最剧烈」的排序从哪来。同一场冲击经过不同的加总渠道被放大或吸收——家庭平滑、投资兜底、劳动边际调整——最后沉淀成可以写进校准靶的相对波动。哪个渠道建模错了，对应的矩就配不上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计冲击、不画识别 IRF。不把金融危机的杠杆事实提前写成 KM 模型。也不做资产定价周期（股权溢价、回报可预测已在别的课程）。发展中国家与战争样本另表。</p><p><span class="marginnote">常见误区：把「事实清单」读成「成因清单」。消费平滑不证明家庭精于计算，工资弱共动也不直接证明工资黏性——同一张矩表可以被好几种完全不同的结构复制出来，事实约束模型，不定罪模型。</span></p><p>后课默认：说到商业周期事实，指声明滤波与样本后的相对波动与共动。下一课：从共动走到结构性冲击，需要识别假设。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>周期事实是相对波动与共动，不是冲击标签。</li><li>消费平滑、投资剧烈、工时顺周期是基准靶。</li><li>多样结构可复制同一张表，故事实不够识别。</li><li>出处：Kydland–Prescott 矩表；Stock and Watson, <em>Handbook of Macroeconomics</em>。</li></ul>',7))])}const b=i(p,[["render",c]]);export{T as __pageData,b as default};
